package kr.jinsu.radio;
import org.junit.Test;
import static org.junit.Assert.*;
import java.time.*;
public class RadioDataTest {
 @Test public void extendedHourBelongsToNextDate(){LocalDate day=LocalDate.of(2026,11,2);assertEquals(RadioData.stamp(day.plusDays(1),"010000"),RadioData.stamp(day,"250000"));}
 @Test public void kstTimezoneDoesNotDependOnDeviceTimezone(){assertEquals(Instant.parse("2026-11-01T15:00:00Z").toEpochMilli(),RadioData.stamp(LocalDate.of(2026,11,2),"00:00"));}
 @Test public void boundariesDoNotOverlap(){RadioData.Program p=new RadioData.Program("program","","","",100,200);assertFalse(p.current(99));assertTrue(p.current(100));assertTrue(p.current(199));assertFalse(p.current(200));}
 @Test public void htmlAndNullMetadataAreSafe(){assertEquals("음악 & 이야기",RadioData.clean("<b>음악</b> &amp; 이야기"));assertEquals("",RadioData.clean("null"));assertEquals("",RadioData.clean(null));}
 @Test public void stationIdsAreUnique(){java.util.Set<String> ids=new java.util.HashSet<>();for(RadioData.Station s:RadioData.STATIONS){assertTrue(ids.add(s.id));assertTrue(!s.hasPrograms()&&s.schedule.isEmpty()||s.schedule.startsWith("https://")||s.schedule.equals("http://tbs.seoul.kr/fm/schedule.do"));}}
 @Test public void ytnNamesAndMidnightRolloverAreParsed(){String html="<div class='time'>23:00 -</div><div class='name'><a>밤의 음악</a></div><div class='time'>00:00 -</div><div class='name'>자정 뉴스</div>";java.util.List<RadioData.Program> p=RadioData.parseYtnSchedule(html,LocalDate.of(2026,11,2));assertEquals(2,p.size());assertEquals("밤의 음악",p.get(0).title);assertEquals(RadioData.stamp(LocalDate.of(2026,11,3),"00:00"),p.get(1).start);}
 @Test public void tbsTableParsesProgramAndHost(){java.util.List<RadioData.Program> p=RadioData.parseTbsSchedule("<tr><td>12:00</td><td class='tleft'>TBS뉴스</td><td></td></tr><tr><td>12:05</td><td><a>오후 &amp; 음악</a></td><td>홍길동</td></tr>",LocalDate.of(2026,11,2));assertEquals("TBS뉴스",p.get(0).title);assertEquals("오후 & 음악",p.get(1).title);assertEquals(p.get(1).start,p.get(0).end);assertEquals("홍길동",p.get(1).host);}
 @Test public void ebsTimelineUsesRadioTitlesAndExtendedHours(){String item="<div class='time'><span>25:00</span></div><div class='tit'><strong><a>새벽 프로그램</a></strong></div>";java.util.List<RadioData.Program> p=RadioData.parseEbsSchedule("<ul class=\"timeline\">"+item+"</ul><ul class=\"timeline\">"+item+"</ul>",LocalDate.of(2026,11,2));assertEquals(1,p.size());assertEquals("새벽 프로그램",p.get(0).title);assertEquals(RadioData.stamp(LocalDate.of(2026,11,3),"01:00"),p.get(0).start);}
 @Test public void defaultSortIsNumericFrequencyAndDoesNotMutateCatalog(){java.util.List<RadioData.Station> p=RadioData.orderedStations("frequency");double last=0;for(RadioData.Station r:p){if(!r.hasPrograms())continue;double f=Double.parseDouble(r.fm);assertTrue(f>=last);last=f;}assertEquals("kbs25",RadioData.STATIONS.get(0).id);assertEquals("89.1",p.get(0).fm);}
 @Test public void nameSortUsesKoreanCollation(){java.util.List<RadioData.Station> p=RadioData.orderedStations("name");java.text.Collator c=java.text.Collator.getInstance(java.util.Locale.KOREAN);c.setStrength(java.text.Collator.SECONDARY);for(int i=1;i<14;i++)assertTrue(c.compare(p.get(i-1).name,p.get(i).name)<=0);assertEquals(RadioData.STATIONS.size(),p.size());}
}
